import logging
from io import BytesIO

from mlflow.exceptions import MlflowException
from mlflow.protos.databricks_pb2 import INVALID_PARAMETER_VALUE

_logger = logging.getLogger(__name__)

_PNG_HEADER = b"\x89PNG"


class _DiffusersAdapterWrapper:
    """
    A pyfunc wrapper that loads a base ``diffusers`` pipeline, applies the stored adapter
    weights, and exposes a text-to-image ``predict`` interface.
    """

    def __init__(self, adapter_path, flavor_conf, model_config=None):
        self._adapter_path = adapter_path
        self._flavor_conf = flavor_conf
        self._model_config = model_config or {}
        self._pipeline = None

    def _resolve_base_model(self):
        # A ``base_model`` entry in the model_config overrides the value stored in the flavor
        # configuration, allowing users to swap the base model at load time.
        if self._model_config and self._model_config.get("base_model"):
            return self._model_config["base_model"]
        return self._flavor_conf["base_model"]

    def _load_pipeline(self):
        if self._pipeline is not None:
            return self._pipeline

        import diffusers

        base_model = self._resolve_base_model()
        from_pretrained_kwargs = {}
        revision = self._flavor_conf.get("base_model_revision")
        if revision:
            from_pretrained_kwargs["revision"] = revision

        try:
            pipeline = diffusers.DiffusionPipeline.from_pretrained(
                base_model, **from_pretrained_kwargs
            )
        except OSError as e:
            raise MlflowException(
                f"Failed to load base model '{base_model}': {e}",
                error_code=INVALID_PARAMETER_VALUE,
            )

        from mlflow.diffusers import _detect_device

        device = _detect_device()
        if device:
            try:
                pipeline = pipeline.to(device)
            except Exception as e:  # noqa: BLE001
                _logger.warning(f"Failed to move pipeline to device '{device}': {e}")

        self._load_adapter_weights(pipeline)
        self._pipeline = pipeline
        return pipeline

    def _load_adapter_weights(self, pipeline):
        load_kwargs = {}
        weight_name = self._flavor_conf.get("weight_name")
        if weight_name:
            load_kwargs["weight_name"] = weight_name
        try:
            pipeline.load_lora_weights(self._adapter_path, **load_kwargs)
        except Exception as e:  # noqa: BLE001
            raise MlflowException(
                f"Failed to load adapter weights from '{self._adapter_path}': {e}",
                error_code=INVALID_PARAMETER_VALUE,
            )

    def get_raw_model(self):
        """Return the underlying (base model + adapter) diffusion pipeline."""
        return self._load_pipeline()

    def _normalize_prompts(self, data):
        import pandas as pd

        if isinstance(data, str):
            prompts = [data]
        elif isinstance(data, list):
            prompts = list(data)
        elif isinstance(data, dict):
            if "prompt" not in data:
                raise MlflowException(
                    "The input dictionary must contain a 'prompt' key.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
            value = data["prompt"]
            if isinstance(value, str):
                prompts = [value]
            elif isinstance(value, list):
                prompts = list(value)
            else:
                raise MlflowException(
                    "The 'prompt' value must be a string or list of strings.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        elif isinstance(data, pd.DataFrame):
            if "prompt" in data.columns:
                prompts = data["prompt"].tolist()
            elif len(data.columns) == 1:
                prompts = data[data.columns[0]].tolist()
            else:
                raise MlflowException(
                    "The input DataFrame must contain a 'prompt' column.",
                    error_code=INVALID_PARAMETER_VALUE,
                )
        else:
            raise MlflowException(
                f"Unsupported input type: {type(data).__name__}. Supported types are string, "
                "list of strings, dict with a 'prompt' key, and pandas DataFrame.",
                error_code=INVALID_PARAMETER_VALUE,
            )

        if len(prompts) == 0:
            raise MlflowException(
                "No prompts provided for inference.", error_code=INVALID_PARAMETER_VALUE
            )
        if any(p is None for p in prompts):
            raise MlflowException(
                "All prompt values must be strings, not None.",
                error_code=INVALID_PARAMETER_VALUE,
            )
        return prompts

    def predict(self, data, params=None):
        prompts = self._normalize_prompts(data)
        pipeline = self._load_pipeline()

        call_kwargs = dict(params) if params else {}
        output = pipeline(prompt=prompts, **call_kwargs)

        images = getattr(output, "images", None)
        if images is None and isinstance(output, dict):
            images = output.get("images")
        if not images:
            raise MlflowException(
                "Pipeline returned no images.", error_code=INVALID_PARAMETER_VALUE
            )

        return [_image_to_png_bytes(image) for image in images]


def _image_to_png_bytes(image):
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)
    buffer = BytesIO()
    image.save(buffer, format="PNG")
    return buffer.getvalue()
